/** Return a new array; missing recent entries sort alphabetically after known ones. */
function arrangeDirectory(results, category, sort, recent) {
	const positions = new Map(recent.map((id, index) => [id, index]));
	return results.filter(({ tool }) => category === "All" || tool.category === category).sort((a, b) => {
		if (sort === "recent") {
			const difference = (positions.get(a.tool.id) ?? Infinity) - (positions.get(b.tool.id) ?? Infinity);
			if (difference && !Number.isNaN(difference)) return difference;
		}
		return a.tool.name.localeCompare(b.tool.name);
	});
}
