/** All entry points must respect approval and maintenance before starting a task. */
function getTaskRoute(tool, task, maintenanceAcknowledged = false) {
	if (!tool.tasks.includes(task)) return "invalid";
	if (["Restricted", "Coming Soon"].includes(tool.access) || ["Outage", "Coming Soon"].includes(tool.status)) return "blocked";
	if (tool.access === "Request access") return "access";
	if (tool.status === "Maintenance" && !maintenanceAcknowledged) return "maintenance";
	const action = tool.quickActions?.find((candidate) => candidate.label === task);
	if (action?.type === "url") return "preview";
	const target = action?.type === "task" ? action.target : task;
	if (tool.id === "service-center" && /report an issue|open a ticket/.test(target)) return "incident";
	if (tool.id === "access-manager" && target === "request access") return "permissions";
	return "preview";
}
